def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]
    moves6, ext5 = [], []
    for y in range(H):
        for x in range(W):
            if g[y, x] != 9:
                continue
            for dy, dx in dirs:
                ny, nx = y+dy, x+dx
                if 0 <= ny < H and 0 <= nx < W and g[ny, nx] in (5, 6):
                    if g[ny, nx] == 6:
                        moves6.append(((y, x), (y+2*dy, x+2*dx)))
                    else:
                        ext5.append((ny, nx))
                    break
    for (src, dst) in moves6:
        out[src] = bg
    for (src, dst) in moves6:
        out[dst] = 9
    emit(out, "Markers touching 6 squares slide two cells inward onto the square's middle line.")
    for c in ext5:
        out[c] = 9
    emit(out, "Markers touching 5 squares extend one cell into the square.")
    out[(out == 5)] = bg
    emit(out, "The 5 squares dissolve into background, leaving only the 2-cell 9 stubs.")
    return out
